import {
  handleHttpError,
  enableNotifications,
} from '/static/js/common/functions.prod.js';
import { showErrorMessage } from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  ($(document).ajaxError(function (t, o) {
    handleHttpError(o.status);
  }),
    document.body.addEventListener('htmx:responseError', function (t) {
      handleHttpError(t.detail.xhr.status);
    }),
    $('main').on('click', '.checkbox', async function () {
      $(this).prop('checked')
        ? await enableNotifications()
        : showErrorMessage(
            gettext('Notifications Silenced'),
            gettext('You will not receive notifications')
          );
    }));
});
